create table if not exists public.tipos_personas (
  "Id_Tipos_Personas" integer generated by default as identity primary key,
  "Descripcion" varchar(100) not null unique
);

create table if not exists public.personas (
  "Id_Personas" integer generated by default as identity primary key,
  "Nombre" varchar(150) not null,
  "Documento" varchar(50) not null unique,
  "Telefono" varchar(30),
  "Activo" boolean not null default true
);

create table if not exists public.personas_tipos (
  "Id_Personas" integer not null references public.personas("Id_Personas") on delete cascade,
  "Id_Tipos_Personas" integer not null references public.tipos_personas("Id_Tipos_Personas") on delete restrict,
  primary key ("Id_Personas", "Id_Tipos_Personas")
);

insert into public.tipos_personas ("Descripcion")
values ('Cliente'), ('Funcionario'), ('Proveedor')
on conflict ("Descripcion") do nothing;
